import java.util.ArrayList;
import java.util.List;

/**
 * The insured items of a policy that have not yet answered for a damage in this incident.
 *
 * The office reads a damage report one entry at a time and strikes off the item that
 * answers for it, so that no item answers twice within one incident.
 */
public class UnclaimedCover {

    private final List<Item> unclaimed;

    public UnclaimedCover(List<Item> items) {
        this.unclaimed = new ArrayList<>(items);
    }

    public Item claimAgainst(Damage damage) {
        for (int position = 0; position < unclaimed.size(); position++) {
            if (unclaimed.get(position).type().equals(damage.itemType())) {
                return unclaimed.remove(position);
            }
        }
        throw new ClaimOfficeException(
                "The policy does not cover a further item of type " + damage.itemType());
    }
}
=== InsuredItems.java ===
import java.util.List;

/**
 * The items a policy covers, asked which of them a reported damage concerns.
 *
 * A damage report names only a type, so the office has to look the damaged item up among
 * the items the policy insures before any clause can be applied to it. That lookup is the
 * policy's knowledge of its own cover, and it is where the office's objections to a damage
 * report outside the cover belong.
 *
 * What the cover is worth is a separate question, answered by the PolicyCover the items
 * add up to.
 */
public class InsuredItems {

    private final List<Item> items;

    public InsuredItems(List<Item> items) {
        this.items = items;
    }

    public PolicyCover cover() {
        return PolicyCover.of(items);
    }

    /**
     * The items this cover has left to answer for damages, each usable once.
     */
    public UnclaimedCover unclaimedCover() {
        return new UnclaimedCover(items);
    }
}
=== PayoutCalculator.java ===
/**
 * What the office pays out for an incident reported against a policy.
 *
 * The office settles an incident one damaged item at a time, and the incident's payout is
 * what those settlements come to. The deductible is withheld per damage event, which is why
 * it belongs to the single settlement and not to the tally.
 */
public class PayoutCalculator {

    private static final int DEDUCTIBLE = 100;

    private final ReimbursementClauses reimbursementClauses = new ReimbursementClauses();

    public int payoutFor(Incident incident, InsuredItems insuredItems) {
        UnclaimedCover unclaimedCover = insuredItems.unclaimedCover();
        double payout = 0;
        for (Damage damage : incident.damages()) {
            payout += settlementFor(damage, unclaimedCover);
        }
        return OfficesFavour.onAmountPaidOut(payout);
    }

    /**
     * What one damaged item is settled at: the damage the office reimburses under the
     * clauses that cover it, less the deductible it withholds for every damage event.
     */
    private double settlementFor(Damage damage, UnclaimedCover unclaimedCover) {
        return reimbursementClauses.reimbursedAmountFor(damage, unclaimedCover.claimAgainst(damage))
                - DEDUCTIBLE;
    }
}
=== PolicyCover.java ===
import java.util.List;

/**
 * What a policy is worth to the office: the insurance sum it has underwritten, and the
 * cap on everything it will ever pay out on that policy.
 *
 * The insurance sum is the plain sum of the listed insurance values of the covered items.
 * It is deliberately taken from the price list rather than from the premium: a block
 * discount lowers what the customer pays without lowering what the office insures, and a
 * risk surcharge raises the premium without raising the cap.
 */
public class PolicyCover {

    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

    private final int insuranceSum;

    private PolicyCover(int insuranceSum) {
        this.insuranceSum = insuranceSum;
    }

    public static PolicyCover of(List<Item> items) {
        PriceList priceList = new PriceList();
        int sum = 0;
        for (Item item : items) {
            sum += priceList.insuranceValueOf(item);
        }
        return new PolicyCover(sum);
    }

    /**
     * The ceiling the office underwrote: everything it will ever pay out on this policy,
     * twice the insurance sum.
     */
    public int cap() {
        return CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum;
    }
}
=== Policy.java ===
import java.util.List;

/**
 * A policy the office has issued: what it covers, and what is left of its cap.
 *
 * The cap is what the office will ever pay out on the policy, so it is consumed as claims
 * are settled: a claim is paid only as far as the cap still reaches, and what it does not
 * reach is not paid at all.
 */
public class Policy {

    private final InsuredItems insuredItems;

    private int remainingCap;

    public Policy(List<Item> items) {
        this.insuredItems = new InsuredItems(items);
        this.remainingCap = insuredItems.cover().cap();
    }

    public InsuredItems insuredItems() {
        return insuredItems;
    }

    public int settle(int desiredPayout) {
        int payout = Math.min(desiredPayout, remainingCap);
        remainingCap -= payout;
        return payout;
    }

    public int remainingCap() {
        return remainingCap;
    }
}
=== ReimbursementClauses.java ===
/**
 * The clauses under which the office reimburses a reported damage, before the deductible.
 *
 * The office reimburses damage in full unless a special clause says otherwise. Damage to a
 * highly enchanted item is reimbursed at half, the magic having borne part of the harm.
 * Each clause fixes the share of a damage the office reimburses on the item that suffered
 * it; full reimbursement is what stands when no special clause speaks.
 *
 * The office states a second clause: damage to an item of dragon material is reimbursed in
 * full. It is deliberately absent here. Full reimbursement is already what stands when no
 * clause speaks, so where the dragon clause alone applies it asks for the amount the office
 * would pay anyway; and where it meets the half clause, the office rules that the half
 * clause wins. No damage the office can be shown is settled differently for knowing the
 * item is of dragon material, so naming it would add a distinction without a difference.
 * That precedence — the half clause prevailing over any clause of full reimbursement — is
 * what the single condition below quietly obeys, and is the rule to restate should a clause
 * ever arrive that does make a difference.
 */
public class ReimbursementClauses {

    private static final double HALF_REIMBURSEMENT_RATE = 0.50;

    private static final double FULL_REIMBURSEMENT_RATE = 1.00;

    /** The enchantment level from which the office reimburses a damage at half. */
    private static final int HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;

    public double reimbursedAmountFor(Damage damage, Item damagedItem) {
        return damage.amount() * reimbursedShareOf(damagedItem);
    }

    /** The share of a damage the office reimburses on the item that suffered it. */
    private double reimbursedShareOf(Item damagedItem) {
        if (isHighlyEnchanted(damagedItem)) {
            return HALF_REIMBURSEMENT_RATE;
        }
        return FULL_REIMBURSEMENT_RATE;
    }

    private boolean isHighlyEnchanted(Item item) {
        return item.enchantment() >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
    }
}
